function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
async function get(path){const response=await fetch(origin()+path,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());return response.json()}
function compactMap(values,limit=10){if(!values||typeof values!=='object'||Array.isArray(values))return values;const rows=[];for(const [symbol,raw] of Object.entries(values)){const value=Number(raw);if(Number.isFinite(value))rows.push({symbol,value})}rows.sort((a,b)=>a.value-b.value);return{item_count:Object.keys(values).length,finite_count:rows.length,bottom:rows.slice(0,limit),top:rows.slice(Math.max(0,rows.length-limit)).reverse()}}
function compactPreview(payload){const output={...payload},result=payload&&payload.result&&typeof payload.result==='object'?{...payload.result}:null;if(!result)return output;if(Array.isArray(result.universe)){result.universe_count=result.universe.length;result.universe_sample=result.universe.slice(0,20);delete result.universe}if(result.signal&&typeof result.signal==='object'){result.signal={...result.signal};if(result.signal.scores&&typeof result.signal.scores==='object')result.signal.scores=compactMap(result.signal.scores)}if(result.decision&&typeof result.decision==='object'){result.decision={...result.decision};if(result.decision.target_weights&&Object.keys(result.decision.target_weights).length>20)result.decision.target_weights=compactMap(result.decision.target_weights)}output.result=result;return output}
async function run(input){if(input.confirm_python_execution!==true)throw new Error('Strategy preview requires explicit Python execution confirmation');const id=String(input.project_id||'').trim();if(!id)throw new Error('project_id is required');const base='/api/strategy/projects/'+encodeURIComponent(id);const project=await get(base);if(project.dirty)throw new Error('Save the project source before previewing it');const revision=Number(project.current_revision);const pkg=await get(base+'/revisions/'+revision);const response=await fetch(origin()+base+'/preview',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify({operation:input.action,profile:'runtime',revision,...(input.as_of_date?{as_of_date:String(input.as_of_date)}:{}),confirm_python_execution:true})});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());const result=await response.json();if(result.revision!==revision||result.source_sha256!==pkg.source_sha256)throw new Error('Strategy source package changed during preview');return{...compactPreview(result),strategy_source_package:{project_id:id,revision,source_sha256:pkg.source_sha256}}}
